def choose_move(observation):
    wx, hy = observation.get('grid_width', 0), observation.get('grid_height', 0)
    px, py = observation.get('self_position', (0, 0))
    oppx, oppy = observation.get('opponent_position', (0, 0))
    obstacles = set(map(tuple, observation.get('obstacles', [])))
    resources = set(map(tuple, observation.get('resources', [])))
    remaining = observation.get('remaining_resource_count', 0)
    score_self, score_opp = observation.get('scores', [0, 0])
    my_path = observation.get('self_path', [])
    opp_path = observation.get('opponent_path', [])
    def move_towards(a, b):
        dx, dy = 0, 0
        if a[0] < b[0]: dx = 1
        elif a[0] > b[0]: dx = -1
        elif a[1] < b[1]: dy = 1
        elif a[1] > b[1]: dy = -1
        return dx, dy
    def safe_move(dx, dy):
        nx, ny = px + dx, py + dy
        if (nx, ny) in obstacles or not (0 <= nx < wx and 0 <= ny < hy):
            return False
        return True
    # Move towards closest resource if available
    if resources:
        targets = list(resources)
        targets.sort(key=lambda t: abs(t[0] - px) + abs(t[1] - py))
        for tx, ty in targets:
            dx, dy = move_towards((px, py), (tx, ty))
            if safe_move(dx, dy):
                return [dx, dy]
    # Else, move towards opponent to pursue
    dx, dy = move_towards((px, py), (oppx, oppy))
    if safe_move(dx, dy):
        return [dx, dy]
    # Fallback: try moving in any direction
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1),(0,0)]:
        if safe_move(dx, dy):
            return [dx, dy]
    # Default to stay in place
    return [0, 0]
